import{a}from"./api.C1xNrEEc.js";import"./hoisted.DWgf2xLV.js";import"./Toast.astro_astro_type_script_index_0_lang.DEjscZYH.js";const s=document.getElementById("loginBtn"),o=document.getElementById("loginBtnText"),i=document.getElementById("loginLoading"),t=document.getElementById("errorMessage");document.getElementById("loginForm").addEventListener("submit",async n=>{n.preventDefault();const d=n.target.usernameOrEmail.value,r=n.target.password.value;s.disabled=!0,o.classList.add("hidden"),i.classList.remove("hidden"),t.classList.add("hidden");try{const e=await a.login({usernameOrEmail:d,password:r});e.success?window.location.href="/":(t.textContent=e.message||"Login failed",t.classList.remove("hidden"))}catch(e){console.error("Login error:",e),t.textContent=e.message||"An error occurred during login",t.classList.remove("hidden")}finally{s.disabled=!1,o.classList.remove("hidden"),i.classList.add("hidden")}});
